    alarm.flash = Math.min(1, alarm.flash + amount * 3.5);
    if (alarm.value >= 1 && alarm.armed) {
      alarm.armed = false;
      alarm.alerted = true;
      alarm.unseen = 0;
      alarm.justFull = true;
      alarm.fulls += 1;
      if (alarm.fulls >= ALARM_CONF.maxFull) alarm.over = true;
