    alarm.flash = Math.max(0, alarm.flash - dt * 2.1);
    if (alarm.value <= ALARM_CONF.resetLevel) {
      alarm.armed = true;
      if (alarm.alerted && alarm.unseen >= ALARM_CONF.escapeTime) {
